const TABS=[{key:"reviews",label:"📝 Paper Reviews",search:!0},{key:"handouts",label:"📘 Handouts",search:!0},{key:"past_papers",label:"📄 Past Papers",search:!0},{key:"lectures",label:"🎥 Short Lectures",search:!0},{key:"extractor",label:"🧠 PDF Extractor",search:!1},{key:"assignments",label:"📤 Assignments",search:!0},{key:"gdb",label:"💬 GDB",search:!0},{key:"community",label:"🌐 Community",search:!1}];let ACTIVE_TAB="reviews",ASSIGN_SUB="files",Q="";function initHeader(){document.getElementById("hdr-wa-btn").href=waLink("Assalam-o-Alaikum, I need help regarding LMS.");const e=document.getElementById("tabs");e.innerHTML=TABS.map(e=>`<button class="tab-btn ${e.key===ACTIVE_TAB?"active":""}" data-tab="${e.key}">${e.label}</button>`).join(""),e.querySelectorAll(".tab-btn").forEach(e=>e.addEventListener("click",()=>{ACTIVE_TAB=e.dataset.tab,Q="",renderAll()}))}function renderAll(){document.querySelectorAll(".tab-btn").forEach(e=>e.classList.toggle("active",e.dataset.tab===ACTIVE_TAB));const e=TABS.find(e=>e.key===ACTIVE_TAB);document.getElementById("search-row").innerHTML=e.search?`<div class="card p-3 flex items-center gap-3"><i class="fa-solid fa-magnifying-glass text-ink/30 ml-1"></i><input id="q-input" value="${Q}" placeholder="Search by course code..." class="w-full bg-transparent outline-none text-sm"></div>`:"",e.search&&document.getElementById("q-input").addEventListener("input",e=>{Q=e.target.value,renderList()}),renderList()}function matchQ(e){return!Q||(e||"").toUpperCase().includes(Q.toUpperCase())}function renderList(){const e=document.getElementById("tab-content"),t=window.DATA||{};return"reviews"===ACTIVE_TAB?renderReviews(e,t.paper_reviews||[]):"handouts"===ACTIVE_TAB?renderFiles(e,t.handouts||[],"Handout","fa-book"):"past_papers"===ACTIVE_TAB?renderPastPapers(e,t.past_papers||[]):"lectures"===ACTIVE_TAB?renderLectures(e,t.short_lectures||[]):"extractor"===ACTIVE_TAB?renderExtractor(e):"assignments"===ACTIVE_TAB?renderAssignments(e,t.assignments||[],t.assignment_copy||[]):"gdb"===ACTIVE_TAB?renderCopyList(e,t.gdb_copy||[],"No GDB solutions yet."):"community"===ACTIVE_TAB?renderCommunity(e,t.community||[]):void 0}function renderReviews(e,t){const n=t.filter(e=>matchQ(e.code));e.innerHTML=n.length?`<div class="space-y-4">${n.map(e=>`\n    <div class="card p-5">\n      <div class="flex flex-wrap items-center justify-between gap-3">\n        <span class="badge"><i class="fa-solid fa-book-open mr-1"></i> ${e.code}</span>\n        <div class="flex gap-3 text-[11px] text-ink/50 font-semibold flex-wrap">\n          <span><i class="fa-regular fa-user text-maroon"></i> ${e.by||"—"}</span>\n          <span><i class="fa-regular fa-calendar text-maroon"></i> ${e.date||"—"}</span>\n          <span><i class="fa-regular fa-clock text-maroon"></i> ${e.time||"—"}</span>\n        </div>\n      </div>\n      <div class="bg-ivory rounded-xl p-4 mt-4 space-y-2 border border-ink/5">\n        ${e.content.map((e,t)=>`<p class="text-xs text-ink/70"><span class="inline-flex w-5 h-5 rounded bg-maroon text-white text-[10px] font-bold items-center justify-center mr-2">${t+1}</span>${e}</p>`).join("")}\n      </div>\n    </div>`).join("")}</div>`:emptyState("Abhi koi paper review nahi hai.")}function renderFiles(e,t,n,a){const s=t.filter(e=>matchQ(e.code));e.innerHTML=s.length?`<div class="grid sm:grid-cols-2 gap-4">${s.map(e=>`\n    <div class="card p-5 flex items-center justify-between gap-3">\n      <div class="min-w-0">\n        <span class="badge">${e.code}</span>\n        <p class="font-head font-bold text-sm text-ink mt-2 truncate">${e.title||n}</p>\n      </div>\n      ${e.file_url?`<a target="_blank" href="${e.file_url}" class="btn btn-maroon shrink-0"><i class="fa-solid ${a}"></i> View</a>`:`<a target="_blank" href="${waLink("Please share "+e.code+" "+n+".")}" class="btn btn-outline shrink-0"><i class="fa-brands fa-whatsapp"></i> Ask</a>`}\n    </div>`).join("")}</div>`:emptyState(`Abhi koi ${n.toLowerCase()} nahi hai.`)}function renderPastPapers(e,t){const n=t.filter(e=>matchQ(e.code));e.innerHTML=n.length?`<div class="space-y-4">${n.map(e=>`\n    <div class="card p-5">\n      <span class="badge mb-3 inline-block"><i class="fa-solid fa-layer-group mr-1"></i> ${e.code} — ${e.files.length} file${e.files.length>1?"s":""}</span>\n      <div class="flex flex-wrap gap-2">\n        ${e.files.map(e=>`<a target="_blank" href="${e.url}" class="btn btn-outline"><i class="fa-solid fa-file-pdf text-red-500"></i> ${e.name}</a>`).join("")}\n      </div>\n    </div>`).join("")}</div>`:emptyState("Abhi koi past paper nahi hai.")}function renderLectures(e,t){const n=t.filter(e=>matchQ(e.code));e.innerHTML=n.length?`<div class="grid sm:grid-cols-2 gap-4">${n.map(e=>`\n    <div class="card p-5 flex items-center justify-between gap-3">\n      <div class="min-w-0"><span class="badge">${e.code}</span><p class="font-head font-bold text-sm text-ink mt-2 truncate">${e.title}</p></div>\n      <a target="_blank" href="${e.link}" class="btn btn-outline shrink-0"><i class="fa-brands fa-youtube text-red-600"></i> Watch</a>\n    </div>`).join("")}</div>`:emptyState("Abhi koi short lecture nahi hai.")}function renderAssignments(e,t,n){e.innerHTML='\n    <div class="flex gap-2 mb-4 bg-white p-1.5 rounded-xl border border-ink/10 w-fit">\n      <button id="asub-files" class="px-4 py-2 rounded-lg text-xs font-extrabold">📄 Files</button>\n      <button id="asub-copy" class="px-4 py-2 rounded-lg text-xs font-extrabold">⧉ Copy/Paste</button>\n    </div>\n    <div id="asub-area"></div>';const a=()=>{document.getElementById("asub-files").className="px-4 py-2 rounded-lg text-xs font-extrabold "+("files"===ASSIGN_SUB?"bg-maroon text-white":"text-ink/60"),document.getElementById("asub-copy").className="px-4 py-2 rounded-lg text-xs font-extrabold "+("copy"===ASSIGN_SUB?"bg-maroon text-white":"text-ink/60");const e=document.getElementById("asub-area");"files"===ASSIGN_SUB?renderFiles(e,t,"Assignment","fa-file-arrow-down"):renderCopyList(e,n,"Abhi koi copy-paste solution nahi hai.")};document.getElementById("asub-files").onclick=()=>{ASSIGN_SUB="files",a()},document.getElementById("asub-copy").onclick=()=>{ASSIGN_SUB="copy",a()},a()}function renderCopyList(e,t,n){const a=t.filter(e=>matchQ(e.code));e.innerHTML=a.length?`<div class="space-y-4">${a.map((e,t)=>`\n    <div class="card p-5">\n      <div class="flex items-center justify-between gap-3 flex-wrap">\n        <div><span class="badge">${e.code}</span> ${e.title?`<span class="font-head font-bold text-sm text-ink ml-2">${e.title}</span>`:""}</div>\n        <button class="btn btn-gold copy-btn" data-idx="${t}"><i class="fa-regular fa-copy"></i> Copy</button>\n      </div>\n      <pre id="cp-text-${t}" class="bg-ivory rounded-xl p-4 mt-3 text-xs text-ink/70 whitespace-pre-wrap border border-ink/5">${escapeHtml(e.text)}</pre>\n    </div>`).join("")}</div>`:emptyState(n),e.querySelectorAll(".copy-btn").forEach(t=>t.addEventListener("click",()=>{const n=e.querySelector("#cp-text-"+t.dataset.idx).innerText;navigator.clipboard.writeText(n).then(()=>{t.innerHTML='<i class="fa-solid fa-check"></i> Copied!',setTimeout(()=>t.innerHTML='<i class="fa-regular fa-copy"></i> Copy',1500)})}))}function renderExtractor(e){e.innerHTML='\n    <div class="card p-6 max-w-2xl mx-auto text-center">\n      <div class="w-16 h-16 mx-auto rounded-2xl bg-gradient-to-br from-maroon to-maroon-deep text-white flex items-center justify-center text-2xl shadow-lg"><i class="fa-solid fa-file-shield"></i></div>\n      <h3 class="font-head font-extrabold text-lg text-ink mt-4">Smart PDF Extractor</h3>\n      <p class="text-xs text-ink/50 mt-2">Koi bhi PDF (paper, handout, assignment) upload karein, iska text/questions nikal kar copy karne ke liye tayyar mil jayenge — kahin bhi paste kar sakte hain.</p>\n      <label class="btn btn-maroon mt-5 cursor-pointer inline-flex"><i class="fa-solid fa-cloud-arrow-up"></i> Choose PDF <input type="file" accept="application/pdf" class="hidden" id="pdfx-input"></label>\n      <p id="pdfx-status" class="text-xs font-semibold mt-3 text-ink/50"></p>\n    </div>\n    <div id="pdfx-result" class="max-w-2xl mx-auto mt-5"></div>',document.getElementById("pdfx-input").addEventListener("change",onPdfExtract)}async function onPdfExtract(e){const t=e.target.files[0];if(!t)return;const n=document.getElementById("pdfx-status"),a=document.getElementById("pdfx-result");n.textContent="Extracting text...",a.innerHTML="";try{if("undefined"==typeof pdfjsLib)throw new Error("PDF library abhi load ho rahi hai, thodi der mein dobara try karein.");pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const e=await t.arrayBuffer(),s=await pdfjsLib.getDocument({data:e}).promise;let i="";for(let e=1;e<=s.numPages;e++){const t=await s.getPage(e);i+=(await t.getTextContent()).items.map(e=>e.str).join(" ")+"\n\n"}n.textContent=`✅ ${s.numPages} page(s) se text nikal liya.`,a.innerHTML=`<div class="card p-5">\n      <div class="flex items-center justify-between mb-3"><p class="font-head font-bold text-sm">Extracted Text</p><button id="pdfx-copy" class="btn btn-gold"><i class="fa-regular fa-copy"></i> Copy All</button></div>\n      <pre id="pdfx-text" class="bg-ivory rounded-xl p-4 text-xs text-ink/70 whitespace-pre-wrap border border-ink/5 max-h-96 overflow-y-auto">${escapeHtml(i.trim())}</pre></div>`,document.getElementById("pdfx-copy").addEventListener("click",()=>{navigator.clipboard.writeText(document.getElementById("pdfx-text").innerText),document.getElementById("pdfx-copy").innerHTML='<i class="fa-solid fa-check"></i> Copied!'})}catch(e){n.textContent="❌ "+e.message}}function renderCommunity(e,t){const n=t.filter(e=>"WhatsApp Group"===e.type),a=t.filter(e=>"WhatsApp Channel"===e.type),s=t.filter(e=>"YouTube Channel"===e.type),i=(e,t,n,a)=>n.length?`<div><h4 class="font-head font-bold text-sm text-ink/70 mb-2">${t} ${e}</h4><div class="flex flex-wrap gap-2 mb-5">${n.map(e=>`<a target="_blank" href="${e.link}" class="btn ${a}">${e.name}</a>`).join("")}</div></div>`:"";e.innerHTML=`<div class="card p-6">\n    ${i("WhatsApp Groups","💬",n,"btn-green")}\n    ${i("WhatsApp Channels","📢",a,"btn-green")}\n    ${i("YouTube Channel","🎥",s,"btn-maroon")}\n    ${t.length?"":emptyState("Abhi koi community link add nahi hua.")}\n  </div>`}function emptyState(e){return`<div class="empty-state">${e}</div>`}function escapeHtml(e){const t=document.createElement("div");return t.innerText=e||"",t.innerHTML}document.addEventListener("DOMContentLoaded",initHeader);